document.querySelectorAll('.randomizer_button_wrapper').forEach(wrapper => {
  // --- hover slideshow (from before) ---
  const slides = wrapper.querySelectorAll('.slide-img:not(.is-static)');
  let index = 0, interval = null;

  wrapper.addEventListener('mouseenter', () => {
    slides[index]?.classList.add('is-active');
    interval = setInterval(() => {
      slides[index]?.classList.remove('is-active');
      index = (index + 1) % slides.length;
      slides[index]?.classList.add('is-active');
    }, 220);
  });

  wrapper.addEventListener('mouseleave', () => {
    clearInterval(interval);
    slides.forEach(s => s.classList.remove('is-active'));
    index = 0;
  });

  // --- random URL picker ---
  const btn = wrapper.querySelector('.randomizer_filter');
  if (!btn) return;

  btn.addEventListener('click', () => {
    const raw = wrapper.dataset.urls;
    if (!raw) return;

    const urls = raw.split(',').map(u => u.trim()).filter(Boolean);
    const picked = urls[Math.floor(Math.random() * urls.length)];

    window.location.href = window.location.origin + picked;
  });
});

// External links
document.addEventListener("DOMContentLoaded", () => {
  const links = document.querySelectorAll("a[href]");

  links.forEach((link) => {
    const url = new URL(link.href, window.location.origin);

    const isExternal = url.origin !== window.location.origin;

    if (isExternal) {
      link.setAttribute("target", "_blank");
      link.setAttribute("rel", "noopener noreferrer");
    }
  });
});

// Locaties filter
document.addEventListener("DOMContentLoaded", () => {
  const wrappers = Array.from(document.querySelectorAll(".locations_wrapper"));
  const filters = Array.from(
    document.querySelectorAll('input[data-filter-group="activiteiten"]')
  );

  if (!wrappers.length || !filters.length || typeof gsap === "undefined") return;

  function normalize(value) {
    return (value || "")
      .toString()
      .trim()
      .toLowerCase()
      .replace(/\s+/g, "-")
      .replace(/_/g, "-");
  }

  function getSelectedValues() {
    return filters
      .filter((input) => input.checked)
      .map((input) => normalize(input.getAttribute("data-filter-value")));
  }

  function animateIn(wrapper) {
    clearTimeout(wrapper._hideTimer);

    if (wrapper.style.display === "none") {
      wrapper.style.display = "";
    }

    gsap.killTweensOf(wrapper);

    gsap.fromTo(
      wrapper,
      {
        opacity: 0,
        y: 20
      },
      {
        opacity: 1,
        y: 0,
        duration: 0.45,
        ease: "power1.out",
        overwrite: true
      }
    );
  }

  function animateOut(wrapper) {
    clearTimeout(wrapper._hideTimer);
    gsap.killTweensOf(wrapper);

    gsap.to(wrapper, {
      opacity: 0,
      y: 20,
      duration: 0.35,
      ease: "power1.in",
      overwrite: true,
      onComplete: () => {
        wrapper.style.display = "none";
      }
    });
  }

  function updateWrappers() {
    const selected = getSelectedValues();

    wrappers.forEach((wrapper) => {
      const value = normalize(wrapper.getAttribute("data-filter-activiteiten"));
      const shouldShow = selected.length === 0 || selected.includes(value);
      const isHidden = window.getComputedStyle(wrapper).display === "none";

      if (shouldShow && isHidden) {
        animateIn(wrapper);
      } else if (!shouldShow && !isHidden) {
        animateOut(wrapper);
      }
    });
  }

  filters.forEach((input) => {
    input.addEventListener("change", updateWrappers);
  });

  wrappers.forEach((wrapper) => {
    gsap.set(wrapper, { opacity: 1, y: 0 });
  });

  updateWrappers();
});

//Project Filters
document.addEventListener("DOMContentLoaded", () => {
  const filters = document.querySelectorAll('input[type="checkbox"][data-filter-group][data-filter-value]');
  const items = document.querySelectorAll(".project-card");
  const noResults = document.querySelector(".no_results");

  if (!filters.length || !items.length) return;

  const normalize = (s) =>
    (s || "")
      .toString()
      .toLowerCase()
      .trim()
      .replace(/&/g, "en")
      .replace(/[^\w\s-]/g, "")
      .replace(/\s+/g, " ");

  const parseValues = (raw) =>
    (raw || "")
      .split(/,|•|\n|\r|\t/gi)
      .map(normalize)
      .filter(Boolean);

  function getActive(group) {
    return [...document.querySelectorAll(`input[type="checkbox"][data-filter-group="${group}"]:checked`)]
      .map((el) => normalize(el.getAttribute("data-filter-value")))
      .filter(Boolean);
  }

  function matches(itemValues, activeValues) {
    if (!activeValues.length) return true;
    return activeValues.some((v) => itemValues.includes(v));
  }

  const projectData = Array.from(items).map((item) => {
    const themes = parseValues(item.getAttribute("data-project-themes"));
    const status = parseValues(item.getAttribute("data-project-status"));

    return {
      item,
      themes,
      status
    };
  });

  function hideItem(item) {
    item.style.opacity = "0";
    clearTimeout(item._hideTimer);
    item._hideTimer = setTimeout(() => {
      item.style.display = "none";
    }, 200);
  }

  function showItem(item) {
    clearTimeout(item._hideTimer);
    if (item.style.display === "none") {
      item.style.display = "";
      requestAnimationFrame(() => {
        item.style.opacity = "1";
      });
    } else {
      item.style.opacity = "1";
    }
  }

  function updateNoResults() {
    if (!noResults) return;
    const visible = [...items].some((item) => item.style.display !== "none");
    noResults.style.display = visible ? "none" : "block";
  }

  function updateFilters() {
    const activeThemes = getActive("themes");
    const activeStatus = getActive("status");

    projectData.forEach(({ item, themes, status }) => {
      const show =
        matches(themes, activeThemes) &&
        matches(status, activeStatus);

      if (show) {
        showItem(item);
      } else {
        hideItem(item);
      }
    });

    updateNoResults();
  }

  items.forEach((item) => {
    item.style.transition = "opacity 0.2s ease";
  });

  if (noResults) {
    noResults.style.display = "none";
  }

  filters.forEach((filter) => {
    filter.addEventListener("change", updateFilters);
  });

  updateFilters();
});

//Magnetic Button
document.addEventListener("DOMContentLoaded", () => {
  initMagneticButtons();
});

function initMagneticButtons() {
  const buttons = document.querySelectorAll(".magnetic_cta");

  buttons.forEach((button) => {
    const inner = button.querySelector(".magnetic_cta_inner");
    if (!inner) return;

    let bounds = null;

    function updateBounds() {
      bounds = button.getBoundingClientRect();
    }

    function handleMove(event) {
      if (!bounds) updateBounds();

      const relX = event.clientX - bounds.left;
      const relY = event.clientY - bounds.top;

      const centerX = bounds.width / 2;
      const centerY = bounds.height / 2;

      const moveX = relX - centerX;
      const moveY = relY - centerY;
      
      gsap.to(button, {
        x: moveX * 0.18,
        y: moveY * 0.18,
        duration: 0.22,
        ease: "power3.out",
        overwrite: true
      });
   
      gsap.to(inner, {
        x: moveX * 0.22,
        y: moveY * 0.22,
        duration: 0.28,
        ease: "power3.out",
        overwrite: true
      });
    }

    function handleEnter() {
      updateBounds();
    }

    function handleLeave() {
      gsap.to(button, {
        x: 0,
        y: 0,
        duration: 0.45,
        ease: "elastic.out(1, 0.4)",
        overwrite: true
      });

      gsap.to(inner, {
        x: 0,
        y: 0,
        duration: 0.55,
        ease: "elastic.out(1, 0.35)",
        overwrite: true
      });
    }

    button.addEventListener("mouseenter", handleEnter);
    button.addEventListener("mousemove", handleMove);
    button.addEventListener("mouseleave", handleLeave);
    window.addEventListener("resize", updateBounds);
  });
}

