//Agenda filters
document.addEventListener("DOMContentLoaded", () => {
  const filters = document.querySelectorAll('input[type="checkbox"][data-filter-group][data-filter-value]');
  const items = document.querySelectorAll(".card_item");
  const noResults = document.querySelector(".no_results");

  if (!filters.length || !items.length) return;

  function getActive(group) {
    return [...document.querySelectorAll(`input[type="checkbox"][data-filter-group="${group}"]:checked`)]
      .map((el) => (el.getAttribute("data-filter-value") || "").toLowerCase().trim())
      .filter(Boolean);
  }

  function matches(itemValues, activeValues) {
    if (!activeValues.length) return true;
    return activeValues.some((v) => itemValues.includes(v));
  }

  function getTimeTags(dateString) {
    if (!dateString) return [];

    const eventDate = new Date(dateString);
    if (isNaN(eventDate)) return [];

    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const startOfEventDay = new Date(eventDate.getFullYear(), eventDate.getMonth(), eventDate.getDate());

    const day = startOfToday.getDay();
    const mondayOffset = day === 0 ? -6 : 1 - day;

    const startOfWeek = new Date(startOfToday);
    startOfWeek.setDate(startOfToday.getDate() + mondayOffset);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 7);

    const startOfMonth = new Date(startOfToday.getFullYear(), startOfToday.getMonth(), 1);
    const endOfMonth = new Date(startOfToday.getFullYear(), startOfToday.getMonth() + 1, 1);

    const tags = [];

    if (startOfEventDay >= startOfWeek && startOfEventDay < endOfWeek) tags.push("week");
    if (startOfEventDay >= startOfMonth && startOfEventDay < endOfMonth) tags.push("month");
    if (startOfEventDay >= endOfMonth) tags.push("future");

    return tags;
  }

  function getSeasonTag(dateString) {
    if (!dateString) return [];

    const eventDate = new Date(dateString);
    if (isNaN(eventDate)) return [];

    const month = eventDate.getMonth() + 1;

    if (month === 12 || month === 1 || month === 2) return ["winter"];
    if (month >= 3 && month <= 5) return ["lente"];
    if (month >= 6 && month <= 8) return ["zomer"];
    return ["herfst"];
  }

  function hideItem(item) {
    item.style.opacity = "0";
    clearTimeout(item._hideTimer);
    item._hideTimer = setTimeout(() => {
      item.style.display = "none";
    }, 200);
  }

  function showItem(item) {
    clearTimeout(item._hideTimer);
    if (item.style.display === "none") {
      item.style.display = "";
      requestAnimationFrame(() => {
        item.style.opacity = "1";
      });
    } else {
      item.style.opacity = "1";
    }
  }

  function updateNoResults() {
    if (!noResults) return;
    const visible = [...items].some((item) => item.style.display !== "none");
    noResults.style.display = visible ? "none" : "block";
  }

  function updateFilters() {
    const activeTime = getActive("time");
    const activeSeason = getActive("season");

    items.forEach((item) => {
      const eventDate = item.getAttribute("data-event-date");
      const itemTime = getTimeTags(eventDate);
      const itemSeason = getSeasonTag(eventDate);

      const show = matches(itemTime, activeTime) && matches(itemSeason, activeSeason);

      if (show) {
        showItem(item);
      } else {
        hideItem(item);
      }
    });

    updateNoResults();
  }

  items.forEach((item) => {
    item.style.transition = "opacity 0.2s ease";
  });

  if (noResults) {
    noResults.style.display = "none";
  }

  filters.forEach((filter) => {
    filter.addEventListener("change", updateFilters);
  });

  updateFilters();
});

// Search
document.addEventListener("DOMContentLoaded", () => {
  const triggers = document.querySelectorAll(".search_icon");
  const modal = document.querySelector(".search_modal");

  if (!triggers.length || !modal || typeof gsap === "undefined") return;

  let isOpen = false;
  let isAnimating = false;

  gsap.set(modal, {
    display: "none",
    opacity: 0,
    y: -8
  });

  function openModal() {
    if (isOpen || isAnimating) return;
    isAnimating = true;
    isOpen = true;

    gsap.set(modal, { display: "flex" });

    gsap.to(modal, {
      opacity: 1,
      y: 0,
      duration: 0.22,
      ease: "power2.out",
      onComplete: () => {
        isAnimating = false;
        const input = modal.querySelector("input, .w-input");
        if (input) input.focus();
      }
    });
  }

  function closeModal() {
    if (!isOpen || isAnimating) return;
    isAnimating = true;
    isOpen = false;

    gsap.to(modal, {
      opacity: 0,
      y: -8,
      duration: 0.18,
      ease: "power2.in",
      onComplete: () => {
        gsap.set(modal, { display: "none" });
        isAnimating = false;
      }
    });
  }

  triggers.forEach((trigger) => {
    trigger.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      isOpen ? closeModal() : openModal();
    });
  });
  
  const closeTriggers = document.querySelectorAll(".close_search_icon");

closeTriggers.forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    closeModal();
  });
});

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      closeModal();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeModal();
    }
  });

  document.addEventListener("click", (e) => {
    const clickedTrigger = e.target.closest(".search_icon");
    const clickedInsideModal = e.target.closest(".search_modal");

    if (!clickedTrigger && !clickedInsideModal && isOpen) {
      closeModal();
    }
  });
});

// SplitText animation
gsap.registerPlugin(ScrollTrigger, SplitText)
  
function initHighlightText(){

  let splitHeadingTargets = document.querySelectorAll("[data-highlight-text]")
  splitHeadingTargets.forEach((heading) => {
    
    const scrollStart = heading.getAttribute("data-highlight-scroll-start") || "top 90%"
    const scrollEnd = heading.getAttribute("data-highlight-scroll-end") || "center 40%"
    const fadedValue = heading.getAttribute("data-highlight-fade") || 0.2 // Opacity of letter
    const staggerValue =  heading.getAttribute("data-highlight-stagger") || 0.1 // Smoother reveal
    
    new SplitText(heading, {
      type: "words, chars",
      autoSplit: true,
      onSplit(self) {
        let ctx = gsap.context(() => {
          let tl = gsap.timeline({
            scrollTrigger: {
              scrub: true,
              trigger: heading, 
              start: scrollStart,
              end: scrollEnd,
            }
          })
          tl.from(self.chars,{
            autoAlpha: fadedValue,
            stagger: staggerValue,
            ease: "linear"
          })
        });
        return ctx; // return our animations so GSAP can clean them up when onSplit fires
      }
    });    
  });
}

// Initialize Highlight Text on Scroll
document.addEventListener("DOMContentLoaded", () =>{
  initHighlightText();
});

// Navbar
function normalizeNavValue(value) {
  return (value || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/_/g, "-");
}

function isActuallyVisible(element) {
  return !!(element && (element.offsetWidth || element.offsetHeight || element.getClientRects().length));
}

function getActiveNavbar() {
  const activeNavFromDataset = normalizeNavValue(document.documentElement.dataset.activeNav || "");

  if (activeNavFromDataset) {
    const matchingNavbars = [
      ...document.querySelectorAll(`.navbar[data-nav="${activeNavFromDataset}"]`)
    ];

    return matchingNavbars.find(isActuallyVisible) || matchingNavbars[0] || null;
  }

  return [...document.querySelectorAll(".navbar[data-nav]")].find(isActuallyVisible) || null;
}

function updateMobileMenuTop(navbar) {
  const nav = navbar?.querySelector(".nav_wrapper");
  if (!nav) return;

  const rect = nav.getBoundingClientRect();
  document.documentElement.style.setProperty("--mobile-nav-top", `${rect.bottom}px`);
}

document.addEventListener("DOMContentLoaded", () => {
  const navbar = getActiveNavbar();

  if (!navbar) {
    console.warn("No active navbar found");
    return;
  }

  updateMobileMenuTop(navbar);
  initTabbarDropdown(navbar);
  initMegaMenu(navbar);
  initMobileHamburger(navbar);

  window.addEventListener("resize", () => updateMobileMenuTop(navbar));
  window.addEventListener("scroll", () => updateMobileMenuTop(navbar), { passive: true });
});

// Tabbar
function initTabbarDropdown(navbar) {
  const mobileBreakpoint = 991;
  const wrapper = navbar.querySelector(".tabbar_wrapper");

  if (!wrapper) return;

  const activeItem = wrapper.querySelector(".tab_item.is--active");
  const allItems = Array.from(wrapper.querySelectorAll(".tab_item"));
  const arrow = activeItem ? activeItem.querySelector(".tabbar_dropdown") : null;
  const otherItems = allItems.filter((item) => !item.classList.contains("is--active"));

  if (!activeItem || !otherItems.length) return;

  let isOpen = false;
  let isAnimating = false;

  function isMobile() {
    return window.innerWidth <= mobileBreakpoint;
  }

  function setDesktopState() {
    isOpen = false;
    isAnimating = false;

    allItems.forEach((item) => {
      item.style.display = "";
      item.style.opacity = "";
      item.style.transform = "";
    });

    if (arrow) {
      gsap.set(arrow, { clearProps: "transform" });
    }
  }

  function setMobileClosedState() {
    isOpen = false;
    activeItem.style.display = "flex";

    otherItems.forEach((item) => {
      gsap.set(item, {
        display: "none",
        opacity: 0,
        y: -6
      });
    });

    if (arrow) {
      gsap.set(arrow, { rotate: 0 });
    }
  }

  function openMenu() {
    if (isAnimating || !isMobile() || !isActuallyVisible(navbar)) return;

    isAnimating = true;
    isOpen = true;

    gsap.set(otherItems, { display: "flex" });

    const tl = gsap.timeline({
      defaults: { ease: "power2.out" },
      onComplete: () => {
        isAnimating = false;
      }
    });

    if (arrow) {
      tl.to(arrow, { rotate: 180, duration: 0.22 }, 0);
    }

    tl.fromTo(
      otherItems,
      { opacity: 0, y: -6 },
      { opacity: 1, y: 0, duration: 0.22, stagger: 0.04 },
      0
    );
  }

  function closeMenu() {
    if (!isOpen || isAnimating || !isMobile()) return;

    isAnimating = true;
    isOpen = false;

    const tl = gsap.timeline({
      defaults: { ease: "power2.inOut" },
      onComplete: () => {
        gsap.set(otherItems, { display: "none" });
        isAnimating = false;
      }
    });

    if (arrow) {
      tl.to(arrow, { rotate: 0, duration: 0.2 }, 0);
    }

    tl.to(
      otherItems,
      {
        opacity: 0,
        y: -6,
        duration: 0.16,
        stagger: 0.03
      },
      0
    );
  }

  function handleResize() {
    if (!isMobile()) {
      setDesktopState();
    } else if (isOpen) {
      activeItem.style.display = "flex";
      gsap.set(otherItems, {
        display: "flex",
        opacity: 1,
        y: 0
      });

      if (arrow) gsap.set(arrow, { rotate: 180 });
    } else {
      setMobileClosedState();
    }
  }

  activeItem.style.cursor = "pointer";

  activeItem.addEventListener("click", function (event) {
    if (!isMobile()) return;

    event.preventDefault();
    event.stopPropagation();

    if (isAnimating) return;

    if (isOpen) {
      closeMenu();
    } else {
      openMenu();
    }
  });

  document.addEventListener("click", function (event) {
    if (!isMobile()) return;
    if (!wrapper.contains(event.target) && isOpen && !isAnimating) {
      closeMenu();
    }
  });

  window.addEventListener("resize", handleResize);

  handleResize();
}

// Hamburger
function initMobileHamburger(navbar) {
  const trigger = navbar.querySelector(".hb_wrapper");
  const menu = navbar.querySelector(".nav_items_wrapper");
  const lines = trigger ? trigger.querySelectorAll(".hb_line") : [];
  const mobileBreakpoint = 991;

  if (!trigger || !menu || lines.length < 3 || typeof gsap === "undefined") return;

  const [line1, line2, line3] = lines;

  let isOpen = false;
  let isAnimating = false;

  function isMobile() {
    return window.innerWidth <= mobileBreakpoint;
  }

  function closeMegaMenuIfOpen() {
    if (typeof navbar._closeMegaMenu === "function") {
      navbar._closeMegaMenu();
    }
  }

  function setClosedState() {
    menu.classList.remove("is-mobile-open");

    gsap.set(menu, {
      display: "none",
      opacity: 0,
      y: -12,
      pointerEvents: "none"
    });

    gsap.set(line1, {
      rotate: 0,
      y: 0,
      transformOrigin: "50% 50%"
    });

    gsap.set(line2, {
      opacity: 1
    });

    gsap.set(line3, {
      rotate: 0,
      y: 0,
      transformOrigin: "50% 50%"
    });

    trigger.setAttribute("aria-expanded", "false");
  }

  function setDesktopState() {
    isOpen = false;
    isAnimating = false;
    menu.classList.remove("is-mobile-open");

    gsap.killTweensOf([menu, line1, line2, line3]);

    gsap.set(menu, {
      clearProps: "all"
    });

    gsap.set(line1, {
      clearProps: "all"
    });

    gsap.set(line2, {
      clearProps: "all"
    });

    gsap.set(line3, {
      clearProps: "all"
    });

    trigger.setAttribute("aria-expanded", "false");
  }

  function openMenu() {
    if (!isMobile() || isOpen || isAnimating) return;

    isOpen = true;
    isAnimating = true;

    gsap.killTweensOf([menu, line1, line2, line3]);
    menu.classList.add("is-mobile-open");

    gsap.set(menu, {
      display: "flex",
      pointerEvents: "none"
    });

    const tl = gsap.timeline({
      defaults: {
        ease: "power2.out"
      },
      onComplete: () => {
        menu.style.pointerEvents = "auto";
        trigger.setAttribute("aria-expanded", "true");
        isAnimating = false;
      }
    });

    tl.to(line1, {
      y: 8,
      rotate: 45,
      duration: 0.22
    }, 0);

    tl.to(line2, {
      opacity: 0,
      duration: 0.16
    }, 0);

    tl.to(line3, {
      y: -8,
      rotate: -45,
      duration: 0.22
    }, 0);

    tl.fromTo(menu, {
      opacity: 0,
      y: -12
    }, {
      opacity: 1,
      y: 0,
      duration: 0.26
    }, 0.04);
  }

  function closeMenu() {
    if (!isMobile() || !isOpen || isAnimating) return;

    isOpen = false;
    isAnimating = true;

    closeMegaMenuIfOpen();
    gsap.killTweensOf([menu, line1, line2, line3]);

    const tl = gsap.timeline({
      defaults: {
        ease: "power2.inOut"
      },
      onComplete: () => {
        menu.classList.remove("is-mobile-open");

        gsap.set(menu, {
          display: "none",
          pointerEvents: "none"
        });

        trigger.setAttribute("aria-expanded", "false");
        isAnimating = false;
      }
    });

    tl.to(menu, {
      opacity: 0,
      y: -12,
      duration: 0.2
    }, 0);

    tl.to(line1, {
      y: 0,
      rotate: 0,
      duration: 0.2
    }, 0);

    tl.to(line2, {
      opacity: 1,
      duration: 0.16
    }, 0.02);

    tl.to(line3, {
      y: 0,
      rotate: 0,
      duration: 0.2
    }, 0);
  }

  function toggleMenu() {
    if (isOpen) {
      closeMenu();
    } else {
      openMenu();
    }
  }

  function handleResize() {
    if (!isMobile()) {
      setDesktopState();
    } else if (!isOpen && !isAnimating) {
      setClosedState();
    }
  }

  trigger.addEventListener("click", (event) => {
    if (!isMobile()) return;

    event.preventDefault();
    event.stopPropagation();

    toggleMenu();
  });

  document.addEventListener("click", (event) => {
    if (!isMobile() || !isOpen || isAnimating) return;

    const clickedCloseTrigger = event.target.closest("[data-close-mobile]");
    if (clickedCloseTrigger) {
      closeMenu();
      return;
    }

    if (!trigger.contains(event.target) && !menu.contains(event.target)) {
      closeMenu();
    }
  });

  document.addEventListener("keydown", (event) => {
    if (!isMobile()) return;
    if (event.key === "Escape" && isOpen) {
      closeMenu();
    }
  });

  window.addEventListener("resize", handleResize);

  if (isMobile()) {
    setClosedState();
  } else {
    setDesktopState();
  }
}

// Mega Menu
function initMegaMenu(navbar) {
  const mobileBreakpoint = 991;
  const megaMenu = navbar.querySelector(".mega_menu_wrapper");
  const megaMenuInner = navbar.querySelector(".mega_menu_inner");
  const overlay = navbar.querySelector(".page_overlay");
  const triggers = [...navbar.querySelectorAll("[data_menu_trigger]")];
  const panels = [...navbar.querySelectorAll("[data_menu_panel]")];

  if (
    !megaMenu ||
    !megaMenuInner ||
    !triggers.length ||
    !panels.length ||
    typeof gsap === "undefined"
  ) {
    return;
  }

  let activeKey = null;
  let currentPanel = null;
  let closeTimer = null;
  let isAnimating = false;

  function isMobile() {
    return window.innerWidth <= mobileBreakpoint;
  }

  function getPanel(key) {
    return panels.find((panel) => panel.getAttribute("data_menu_panel") === key) || null;
  }

  function clearCloseTimer() {
    if (closeTimer) {
      clearTimeout(closeTimer);
      closeTimer = null;
    }
  }

  function setActiveTrigger(key) {
    triggers.forEach((trigger) => {
      const isActive = trigger.getAttribute("data_menu_trigger") === key;
      trigger.classList.toggle("is_active", isActive);

      const arrow = trigger.querySelector(".dropdown_arrow");
      if (!arrow) return;

      gsap.to(arrow, {
        rotate: isActive ? 180 : 0,
        duration: 0.12,
        ease: "power1.out",
        overwrite: true
      });
    });
  }

  function hideAllPanels() {
    panels.forEach((panel) => {
      gsap.set(panel, {
        display: "none",
        opacity: 0,
        y: 0,
        clearProps: "height,position,inset,width,transform"
      });
    });
  }

  function resetAll() {
    clearCloseTimer();
    hideAllPanels();
    setActiveTrigger(null);

    megaMenu.classList.remove("is-mobile-open");
    navbar.classList.remove("is-mega-open");

    if (isMobile()) {
      gsap.set(megaMenuInner, {
        clearProps: "height"
      });
    } else {
      gsap.set(megaMenuInner, {
        height: 0
      });
    }

    gsap.set(megaMenu, {
      pointerEvents: "none"
    });

    if (overlay) {
      gsap.set(overlay, {
        opacity: 0,
        pointerEvents: "none"
      });
      overlay.style.pointerEvents = "none";
    }

    activeKey = null;
    currentPanel = null;
    isAnimating = false;
  }

  function measurePanel(panel) {
    gsap.set(panel, {
      display: "flex",
      position: "absolute",
      visibility: "hidden",
      opacity: 0,
      y: 0
    });

    const height = panel.offsetHeight;

    gsap.set(panel, {
      display: "none",
      clearProps: "position,visibility,opacity,transform"
    });

    return height;
  }

  function openDesktop(key) {
    const nextPanel = getPanel(key);
    if (!nextPanel || isAnimating || !isActuallyVisible(navbar)) return;

    clearCloseTimer();

    navbar.classList.add("is-mega-open");
    setActiveTrigger(key);

    if (activeKey === key && currentPanel === nextPanel) return;

    const oldPanel = currentPanel;
    const targetHeight = measurePanel(nextPanel);

    activeKey = key;
    currentPanel = nextPanel;
    isAnimating = true;

    gsap.killTweensOf([megaMenu, megaMenuInner, nextPanel, oldPanel, overlay].filter(Boolean));

    gsap.set(megaMenu, {
      pointerEvents: "auto"
    });

    gsap.set(nextPanel, {
      display: "flex",
      opacity: 0,
      y: 16
    });

    const tl = gsap.timeline({
      onComplete: () => {
        if (oldPanel && oldPanel !== nextPanel) {
          gsap.set(oldPanel, {
            display: "none",
            opacity: 0,
            y: 0
          });
        }

        isAnimating = false;
      }
    });

    if (overlay) {
      tl.to(overlay, {
        opacity: 1,
        duration: 0.2,
        ease: "power2.out",
        onStart: () => {
          overlay.style.pointerEvents = "auto";
        }
      }, 0);
    }

    if (oldPanel && oldPanel !== nextPanel) {
      tl.to(oldPanel, {
        opacity: 0,
        y: -8,
        duration: 0.18,
        ease: "power2.out"
      }, 0);
    }

    tl.to(megaMenuInner, {
      height: targetHeight,
      duration: 0.4,
      ease: "power3.out"
    }, 0);

    tl.to(nextPanel, {
      opacity: 1,
      y: 0,
      duration: 0.3,
      ease: "power2.out"
    }, 0.08);
  }

  function closeDesktop() {
    if (!currentPanel || isAnimating) return;

    clearCloseTimer();
    isAnimating = true;
    setActiveTrigger(null);

    const panelToClose = currentPanel;
    activeKey = null;
    currentPanel = null;

    gsap.killTweensOf([megaMenu, megaMenuInner, panelToClose, overlay].filter(Boolean));

    const tl = gsap.timeline({
      onComplete: () => {
        hideAllPanels();

        gsap.set(megaMenu, {
          pointerEvents: "none"
        });

        if (overlay) {
          overlay.style.pointerEvents = "none";
        }

        navbar.classList.remove("is-mega-open");
        isAnimating = false;
      }
    });

    tl.to(panelToClose, {
      opacity: 0,
      y: 10,
      duration: 0.2,
      ease: "power2.out"
    }, 0);

    tl.to(megaMenuInner, {
      height: 0,
      duration: 0.32,
      ease: "power3.inOut"
    }, 0.04);

    if (overlay) {
      tl.to(overlay, {
        opacity: 0,
        duration: 0.2,
        ease: "power2.out"
      }, 0);
    }
  }

  function scheduleClose() {
    clearCloseTimer();
    closeTimer = setTimeout(closeDesktop, 120);
  }

  function openMobile(key) {
    const nextPanel = getPanel(key);
    if (!nextPanel || isAnimating || !isActuallyVisible(navbar)) return;

    if (currentPanel === nextPanel) {
      closeMobile();
      return;
    }

    clearCloseTimer();

    const oldPanel = currentPanel;

    activeKey = key;
    currentPanel = nextPanel;
    isAnimating = true;

    setActiveTrigger(key);
    megaMenu.classList.add("is-mobile-open");

    gsap.killTweensOf([megaMenu, megaMenuInner, ...panels, overlay].filter(Boolean));

    gsap.set(megaMenu, {
      pointerEvents: "auto"
    });

    gsap.set(megaMenuInner, {
      clearProps: "height"
    });

    if (overlay) {
      gsap.to(overlay, {
        opacity: 1,
        duration: 0.2,
        ease: "power2.out",
        onStart: () => {
          overlay.style.pointerEvents = "auto";
        }
      });
    }

    if (oldPanel && oldPanel !== nextPanel) {
      gsap.set(oldPanel, {
        display: "flex",
        opacity: 1,
        y: 0
      });
    }

    gsap.set(nextPanel, {
      display: "flex",
      opacity: 0,
      y: -12,
      pointerEvents: "auto"
    });

    const tl = gsap.timeline({
      onComplete: () => {
        if (oldPanel && oldPanel !== nextPanel) {
          gsap.set(oldPanel, {
            display: "none",
            opacity: 0,
            y: 0
          });
        }

        isAnimating = false;
      }
    });

    if (oldPanel && oldPanel !== nextPanel) {
      tl.to(oldPanel, {
        opacity: 0,
        y: -10,
        duration: 0.18,
        ease: "power2.out"
      }, 0);
    }

    tl.to(nextPanel, {
      opacity: 1,
      y: 0,
      duration: 0.24,
      ease: "power2.out"
    }, oldPanel ? 0.05 : 0.04);
  }

  function closeMobile() {
    if (!currentPanel || isAnimating) return;

    const panelToClose = currentPanel;
    currentPanel = null;
    activeKey = null;
    isAnimating = true;

    setActiveTrigger(null);

    gsap.killTweensOf([panelToClose, overlay].filter(Boolean));

    const tl = gsap.timeline({
      onComplete: () => {
        gsap.set(panelToClose, {
          display: "none",
          opacity: 0,
          y: 0,
          pointerEvents: "none"
        });

        megaMenu.classList.remove("is-mobile-open");

        gsap.set(megaMenu, {
          pointerEvents: "none"
        });

        if (overlay) {
          overlay.style.pointerEvents = "none";
        }

        isAnimating = false;
      }
    });

    tl.to(panelToClose, {
      opacity: 0,
      y: -10,
      duration: 0.18,
      ease: "power2.inOut"
    }, 0);

    if (overlay) {
      tl.to(overlay, {
        opacity: 0,
        duration: 0.2,
        ease: "power2.out"
      }, 0);
    }
  }

  function closeAnyMegaMenu() {
    if (isMobile()) {
      closeMobile();
    } else {
      closeDesktop();
    }
  }

  triggers.forEach((trigger) => {
    const key = trigger.getAttribute("data_menu_trigger");
    if (!key) return;

    trigger.addEventListener("mouseenter", () => {
      if (isMobile()) return;
      openDesktop(key);
    });

    trigger.addEventListener("focusin", () => {
      if (isMobile()) return;
      openDesktop(key);
    });

    trigger.addEventListener("click", (event) => {
      if (!isMobile()) return;
      event.preventDefault();
      event.stopPropagation();
      openMobile(key);
    });
  });

  navbar.addEventListener("mouseenter", () => {
    if (isMobile()) return;
    clearCloseTimer();
  });

  navbar.addEventListener("mouseleave", () => {
    if (isMobile()) return;
    scheduleClose();
  });

  megaMenuInner.addEventListener("mouseenter", () => {
    if (isMobile()) return;
    clearCloseTimer();
  });

  megaMenuInner.addEventListener("mouseleave", () => {
    if (isMobile()) return;
    scheduleClose();
  });

  if (overlay) {
    overlay.addEventListener("click", () => {
      if (isMobile()) {
        closeMobile();
      } else {
        closeDesktop();
      }
    });
  }

  document.addEventListener("click", (event) => {
    if (!navbar.contains(event.target)) {
      if (isMobile()) {
        closeMobile();
      } else {
        closeDesktop();
      }
    }
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      if (isMobile()) {
        closeMobile();
      } else {
        closeDesktop();
      }
    }
  });

  window.addEventListener("resize", resetAll);

  navbar._closeMegaMenu = closeAnyMegaMenu;

  resetAll();
}
